import { useEffect, useState } from "react";
import { motion } from "framer-motion";

const branches = ["Nava India", "RS Puram", "Kovaipudur"];

export default function Gallery() {
  const [branch, setBranch] = useState("Nava India");
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);

    fetch(`http://localhost:5000/gallery?branch=${encodeURIComponent(branch)}`)
      .then((res) => {
        if (!res.ok) throw new Error("Server not reachable");
        return res.json();
      })
      .then((data) => setImages(data))
      .catch((err) => console.error("Gallery fetch error:", err))
      .finally(() => setLoading(false));
  }, [branch]);

  const downloadImage = async (url) => {
    const res = await fetch(url);
    const blob = await res.blob();
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "bodyzeal-gallery.jpg";
    link.click();
  };

  return (
    <section className="bg-black py-24 px-6 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <h2 className="text-4xl text-center font-bold mb-12 text-white">
          Our <span className="text-yellow-400">Gallery</span>
        </h2>

        {/* FILTER */}
        <div className="flex justify-center gap-4 mb-12 flex-wrap">
          {branches.map((b) => (
            <button
              key={b}
              onClick={() => setBranch(b)}
              className={`px-6 py-2 rounded-full border transition ${
                branch === b
                  ? "bg-yellow-400 text-black"
                  : "border-yellow-400 text-yellow-400 hover:bg-yellow-400 hover:text-black"
              }`}
            >
              {b}
            </button>
          ))}
        </div>

        {/* LOADING */}
        {loading && (
          <p className="text-center text-gray-400">Loading images...</p>
        )}

        {/* GRID */}
        <div className="grid sm:grid-cols-2 md:grid-cols-3 gap-8">
          {images.slice(0, 6).map((img) => (
            <motion.div
              key={img.id}
              whileHover={{ scale: 1.05 }}
              className="relative overflow-hidden rounded-2xl"
            >
              <img
                src={`http://localhost:5000${img.image_url}`}
                alt="Gallery"
                className="w-full h-72 object-cover"
              />

              <button
                onClick={() =>
                  downloadImage(
                    `http://localhost:5000${img.image_url}`
                  )
                }
                className="absolute bottom-4 right-4 bg-yellow-400 px-4 py-1 rounded-full text-black font-semibold"
              >
                Download
              </button>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
